export function evaluationCollections(specification = knowledgeEvaluationDataset) {
  return specification.documents.map((document, index) => ({
    id:document.id, title:document.title, url:document.url, type:'article', status:'saved', sourceRevision:1,
    input:{ mode:'text', content:document.body }, content:document.body,
    createdAt:`2026-11-${String(index + 1).padStart(2, '0')}T00:00:00Z`,
  }));
}
